<?php $args = array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => absint( get_theme_mod( 'kimpu_portfolio_limit', 6 ) ) ?: -1, 'ignore_sticky_posts' => true ); $category = absint( get_theme_mod( 'kimpu_portfolio_category', 0 ) ); if ( $category ) { $args['cat'] = $category; } $projects = new WP_Query( $args ); ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'portfolio' ) ); ?>" id="portfolio"><div class="container"><?php kimpu_homepage_section_header( 'portfolio' ); ?><?php if ( $projects->have_posts() ) : ?><div class="homepage-card-grid homepage-portfolio-grid"><?php while ( $projects->have_posts() ) : $projects->the_post(); ?><article class="post-card portfolio-card"><?php if ( has_post_thumbnail() ) : ?><a class="post-thumb" href="<?php the_permalink(); ?>"><?php the_post_thumbnail( 'medium_large' ); ?></a><?php endif; ?><div class="post-content"><p class="post-meta"><?php echo wp_kses_post( get_the_category_list( ', ' ) ); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 20 ) ); ?></p></div></article><?php endwhile; ?></div><?php wp_reset_postdata(); else : ?><p class="empty-state"><?php esc_html_e( 'Publish posts and optionally assign a category to populate the portfolio.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
